// Datos INVENTADOS. Registros del sistema viejo: ancho fijo, como los que lee el programa COBOL.
const archivoLegado = [
  "000101FERRETERIA SUR00120018500E",
  "000102LIBRERIA NORTE00030004200P",
  "000103FERRETERIA SUR00070043100E",
  "000104KIOSCO 24 HS  00010000950D",
  "000105LIBRERIA NORTE00050012750E",
];

// 1) El sistema viejo: devuelve texto en su formato.
function legadoConsultar(nro) {
  return archivoLegado.find(l => l.startsWith(String(nro).padStart(6, "0"))) ?? null;
}

// 2) La capa anticorrupción: traduce el formato viejo al modelo nuevo, y solo ella conoce los códigos viejos.
const ESTADOS_LEGADO = { E: "entregado", P: "pendiente", D: "devuelto" };
function traducir(linea) {
  return {
    nro: Number(linea.slice(0, 6)),
    cliente: linea.slice(6, 20).trim(),
    bultos: Number(linea.slice(20, 24)),
    pesoKg: Number(linea.slice(24, 31)) / 100,
    estado: ESTADOS_LEGADO[linea[31]] ?? "desconocido",
  };
}

// 3) El servicio nuevo: ya migrado, con su propio modelo. Un equipo lo escribió leyendo la documentación.
const nuevoStore = new Map(archivoLegado.map(l => {
  const r = traducir(l);
  if (r.estado === "devuelto") r.estado = "rechazado"; // supuesto del equipo nuevo, que nadie verificó
  return [r.nro, r];
}));
function nuevoConsultar(nro) { return nuevoStore.get(nro) ?? null; }

// 4) La fachada: decide a quién le pregunta cada operación. Modos: "legado", "sombra" (pregunta a los dos y responde el viejo) y "nuevo".
const modo = { consultarRemito: "sombra" };
const diferencias = [];
function fachadaConsultar(nro) {
  const m = modo.consultarRemito;
  const viejo = () => { const l = legadoConsultar(nro); return l ? traducir(l) : null; };
  if (m === "legado") return viejo();
  if (m === "nuevo") return nuevoConsultar(nro);
  const a = viejo(), b = nuevoConsultar(nro);
  if (JSON.stringify(a) !== JSON.stringify(b)) diferencias.push({ nro, legado: a?.estado, nuevo: b?.estado });
  return a; // en modo sombra el usuario sigue viendo la respuesta del viejo
}

for (const nro of [101, 102, 103, 104, 105]) fachadaConsultar(nro);
console.log("Modo sombra, 5 consultas. Diferencias encontradas:", diferencias.length);
console.log(JSON.stringify(diferencias));
console.log("Respuesta que ve el usuario (viene del viejo):", JSON.stringify(fachadaConsultar(104)));

// Se corrige el servicio nuevo, se vuelve a comparar y recién entonces se pasa el tráfico.
nuevoStore.get(104).estado = "devuelto";
diferencias.length = 0;
for (const nro of [101, 102, 103, 104, 105]) fachadaConsultar(nro);
console.log("Después de corregir. Diferencias:", diferencias.length);
modo.consultarRemito = "nuevo";
console.log("Ahora responde el nuevo:", JSON.stringify(fachadaConsultar(104)));

